int main() {
    int n, m, p, q, a, b;
    scanf("%d %d %d %d %d %d", &n, &m, &p, &q, &a, &b);

    long long tickets[20];
    for (int k = 0; k < n; k++) {
        long long ak = 1, bk = 1;
        for (int i = 0; i < k; i++) {
            ak *= a;
            bk *= b;
        }
        tickets[k] = p * ak + q * bk;
    }

    long long min_walk = m; // worst case: walk all the way

    // iterate over all subsets
    for (int mask = 0; mask < (1 << n); mask++) {
        long long sum = 0;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                sum += tickets[i];
            }
        }
        if (sum >= m) {
            long long walk = sum - m;
            if (walk < min_walk) min_walk = walk;
