typedef long long ll;

int cmp(const void *a, const void *b) {
    ll x = *(ll*)a, y = *(ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    ll n, m, p, a, q, b;
    scanf("%lld %lld %lld %lld %lld %lld", &n, &m, &p, &a, &q, &b);

    ll *val = (ll*)malloc(n * sizeof(ll));
    ll pw_a = 1, pw_b = 1;
    for (int k = 0; k < n; k++) {
        val[k] = p * pw_a + q * pw_b;
        pw_a *= a;
        pw_b *= b;
    }

    int half1 = n / 2;
    int half2 = n - half1;

    ll sz1 = 1LL << half1;
    ll sz2 = 1LL << half2;

    ll *sums1 = (ll*)malloc(sz1 * sizeof(ll));
    ll *sums2 = (ll*)malloc(sz2 * sizeof(ll));

    for (ll mask = 0; mask < sz1; mask++) {
        ll s = 0;
        for (int i = 0; i < half1; i++)
            if (mask >> i & 1) s += val[i];
        sums1[mask] = s;
    }
    for (ll mask = 0; mask < sz2; mask++) {
        ll s = 0;
        for (int i = 0; i < half2; i++)
            if (mask >> i & 1) s += val[half1 + i];
        sums2[mask] = s;
    }

    qsort(sums2, sz2, sizeof(ll), cmp);

    ll best = 0;
    for (ll i = 0; i < sz1; i++) {
        ll rem = m - sums1[i];
        if (rem < 0) continue;
        // find largest in sums2 <= rem
        ll lo = 0, hi = sz2 - 1, res = -1;
        while (lo <= hi) {
            ll mid = (lo + hi) / 2;
            if (sums2[mid] <= rem) { res = sums2[mid]; lo = mid + 1; }
            else hi = mid - 1;
        }
        if (res >= 0 && sums1[i] + res > best) best = sums1[i] + res;
    }

    printf("%lld\n", m - best);
    free(val); free(sums1); free(sums2);
    return 0;
}

#include <stdio.h>
