typedef long long ll;

static ll absll(ll x) { return x < 0 ? -x : x; }

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    ll p, q, a, b, m;
    if (scanf("%d %lld %lld %lld %lld %lld", &n, &p, &q, &a, &b, &m) != 6) {
        return 0;
    }

    int n1 = n / 2;
    int n2 = n - n1;

    ll *left = (ll*)malloc((size_t)n1 * sizeof(ll));
    ll *right = (ll*)malloc((size_t)n2 * sizeof(ll));
    if (!left || !right) return 0;

    ll curA = 1, curB = 1;
    for (int k = 0; k < n; ++k) {
        ll val = p * curA + q * curB;
        if (k < n1) left[k] = val;
        else right[k - n1] = val;

        if (k != n - 1) {
            curA *= a;
            curB *= b;
        }
    }

    size_t szL = 1ULL << n1;
    size_t szR = 1ULL << n2;

    ll *sumL = (ll*)malloc(szL * sizeof(ll));
    ll *sumR = (ll*)malloc(szR * sizeof(ll));
    if (!sumL || !sumR) return 0;

    sumL[0] = 0;
    for (size_t mask = 1; mask < szL; ++mask) {
        size_t bit = mask & (~mask + 1ULL);
        int idx = 0;
        while (((size_t)1 << idx) != bit) idx++;
        sumL[mask] = sumL[mask ^ bit] + left[idx];
    }

    sumR[0] = 0;
    for (size_t mask = 1; mask < szR; ++mask) {
        size_t bit = mask & (~mask + 1ULL);
        int idx = 0;
        while (((size_t)1 << idx) != bit) idx++;
        sumR[mask] = sumR[mask ^ bit] + right[idx];
    }

    qsort(sumR, szR, sizeof(ll), cmp_ll);

    ll ans = absll(m);  // use no ticket

    for (size_t i = 0; i < szL; ++i) {
        ll need = m - sumL[i];

        size_t lo = 0, hi = szR;
        while (lo < hi) {
            size_t mid = lo + (hi - lo) / 2;
            if (sumR[mid] < need) lo = mid + 1;
            else hi = mid;
        }

        if (lo < szR) {
            ll total = sumL[i] + sumR[lo];
            ll d = absll(m - total);
            if (d < ans) ans = d;
        }
        if (lo > 0) {
            ll total = sumL[i] + sumR[lo - 1];
            ll d = absll(m - total);
            if (d < ans) ans = d;
        }
    }

    printf("%lld\n", ans);

    free(left);
    free(right);
    free(sumL);
    free(sumR);
    return 0;
}

