using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, p, q, a, b;
    cin >> n >> m >> p >> q >> a >> b;

    vector<int64> tickets(n);
    for (int i = 0; i < n; i++) {
        tickets[i] = p * (int64)pow(a, i) + q * (int64)pow(b, i);
    }

    int n1 = n / 2;
    int n2 = n - n1;

    vector<int64> left_sums, right_sums;

    // generate all sums for first half
    for (int mask = 0; mask < (1 << n1); mask++) {
        int64 sum = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i))
                sum += tickets[i];
        }
        left_sums.push_back(sum);
    }

    // generate all sums for second half
    for (int mask = 0; mask < (1 << n2); mask++) {
        int64 sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i))
                sum += tickets[n1 + i];
        }
        right_sums.push_back(sum);
    }

    sort(right_sums.begin(), right_sums.end());
    right_sums.erase(unique(right_sums.begin(), right_sums.end()), right_sums.end());

    int64 best = LLONG_MAX;

    for (int64 s : left_sums) {
        // find closest to m - s
        int64 need = m - s;
        auto it = lower_bound(right_sums.begin(), right_sums.end(), need);
        if (it != right_sums.end()) {
            best = min(best, abs(m - (s + *it)));
        }
        if (it != right_sums.begin()) {
            --it;
            best = min(best, abs(m - (s + *it)));
        }
    }

    cout << best << "\n";

    return 0;
}

