    for (int k = 0; k < n; k++) {
        tickets[k] = p * apow + q * bpow;
        apow *= a;
        bpow *= b;
    }

    // Meet in the middle
    int half1 = n / 2, half2 = n - half1;

    vector<long long> sums1, sums2;
    for (int mask = 0; mask < (1 << half1); mask++) {
        long long s = 0;
        for (int i = 0; i < half1; i++)
            if (mask >> i & 1) s += tickets[i];
        sums1.push_back(s);
    }
    for (int mask = 0; mask < (1 << half2); mask++) {
        long long s = 0;
        for (int i = 0; i < half2; i++)
            if (mask >> i & 1) s += tickets[half1 + i];
        sums2.push_back(s);
    }

    sort(sums2.begin(), sums2.end());

    long long best = LLONG_MAX;
    for (long long s1 : sums1) {
        long long need = m - s1;
        auto it = lower_bound(sums2.begin(), sums2.end(), need);
        if (it != sums2.end()) best = min(best, abs(s1 + *it - m));
        if (it != sums2.begin()) { --it; best = min(best, abs(s1 + *it - m)); }
    }

    cout << best << endl;
    return 0;
