using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, p, a, q, b, m;
    cin >> n >> p >> a >> q >> b >> m;

    // We need min |m - (p*a^k + q*b^k)| for k in [0, n-1].
    // Since values can grow very quickly, compute carefully with saturation.
    long long ans = llabs(m - (p + q)); // k = 0

    i128 pa = p; // p * a^k
    i128 qb = q; // q * b^k

    const i128 LIM = (i128)4e18; // enough for safe saturation

    for (long long k = 0; k < n; ++k) {
        i128 dist = pa + qb;
        i128 diff = dist - (i128)m;
        if (diff < 0) diff = -diff;
        if (diff < ans) ans = (long long)diff;

        if (k + 1 == n) break;

        // advance to k+1 with saturation
        pa = min(LIM, pa * (i128)a);
        qb = min(LIM, qb * (i128)b);
    }

    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class RabbitTickets {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long p = sc.nextLong();
        long q = sc.nextLong();
        long a = sc.nextLong();
        long b = sc.nextLong();
        sc.close();

        // Generate ticket distances
        long[] tickets = new long[(int)n];
        long maxDist = 0;
        for (int i = 0; i < n; i++) {
            tickets[i] = p * (long)Math.pow(a, i) + q * (long)Math.pow(b, i);
            if (tickets[i] > maxDist) maxDist = tickets[i];
        }

        // We'll search up to m + maxDist to allow overshoot
        long limit = m + maxDist;
        if (limit > 1_000_000_000L) limit = 1_000_000_000L; // safety bound

        // Dijkstra: distance array for positions 0..limit
        long[] dist = new long[(int)(limit + 1)];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a2 -> a2[1]));
        pq.offer(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long pos = cur[0];
            long walk = cur[1];
            if (walk != dist[(int)pos]) continue;

            // walking one step
            if (pos + 1 <= limit && dist[(int)(pos + 1)] > walk + 1) {
                dist[(int)(pos + 1)] = walk + 1;
                pq.offer(new long[]{pos + 1, walk + 1});
            }
            if (pos - 1 >= 0 && dist[(int)(pos - 1)] > walk + 1) {
                dist[(int)(pos - 1)] = walk + 1;
                pq.offer(new long[]{pos - 1, walk + 1});
            }

            // using each ticket
            for (long t : tickets) {
                long np = pos + t;
                if (np <= limit && dist[(int)np] > walk) {
                    dist[(int)np] = walk;
                    pq.offer(new long[]{np, walk});
                }
            }
        }

        long answer = Long.MAX_VALUE;
        for (long pos = 0; pos <= limit; pos++) {
            if (dist[(int)pos] != Long.MAX_VALUE) {
                long walkToTarget = Math.abs(m - pos);
                answer = Math.min(answer, dist[(int)pos] + walkToTarget);
            }
        }

        System.out.println(answer);
    }
}

import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long p = sc.nextLong();
        long q = sc.nextLong();
        long a = sc.nextLong();
        long b = sc.nextLong();

        BigInteger M = BigInteger.valueOf(m);
        BigInteger remaining = M;

        // Compute all ticket values
        BigInteger[] vals = new BigInteger[(int)n];
        BigInteger ak = BigInteger.ONE, bk = BigInteger.ONE;
        BigInteger A = BigInteger.valueOf(a), B = BigInteger.valueOf(b);
        BigInteger P = BigInteger.valueOf(p), Q = BigInteger.valueOf(q);
        for (int k = 0; k < n; k++) {
            vals[k] = P.multiply(ak).add(Q.multiply(bk));
            ak = ak.multiply(A);
            bk = bk.multiply(B);
        }

        // Greedy from largest to smallest
        for (int k = (int)n - 1; k >= 0; k--) {
            BigInteger val = vals[k];
            if (remaining.subtract(val).abs().compareTo(remaining.abs()) < 0) {
                remaining = remaining.subtract(val);
            }
        }

        System.out.println(remaining.abs());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long n = fs.nextLong();
        long p = fs.nextLong();
        long a = fs.nextLong();
        long q = fs.nextLong();
        long b = fs.nextLong();
        long m = fs.nextLong();

        // dp[i] = reachable sums after considering first i tickets, stored as bitset.
        // We only care about sums up to m, because overshooting on outbound line is useless.
        BitSet reachable = new BitSet((int) Math.min(m, Integer.MAX_VALUE - 1) + 1);
        reachable.set(0);

        long powA = 1;
        long powB = 1;

        for (long k = 0; k < n; k++) {
            long term1 = safeMul(p, powA, m);
            long term2 = safeMul(q, powB, m);

            long dist;
            if (term1 > m || term2 > m || term1 + term2 > m) {
                dist = m + 1; // larger than useful
            } else {
                dist = term1 + term2;
            }

            if (dist <= m) {
                int d = (int) dist;
                BitSet shifted = shiftLeft(reachable, d, (int) m);
                reachable.or(shifted);
            }

            powA = nextPow(powA, a, m);
            powB = nextPow(powB, b, m);
        }

        int best = reachable.previousSetBit((int) m);
        System.out.println(m - best);
    }

    static long safeMul(long x, long y, long limit) {
        if (x == 0 || y == 0) return 0;
        if (x > limit / y) return limit + 1;
        return x * y;
    }

    static long nextPow(long cur, long base, long limit) {
        if (cur > limit) return limit + 1;
        if (base == 0) return 0;
        if (cur == 0) return 0;
        if (cur > limit / base) return limit + 1;
        return cur * base;
    }

    static BitSet shiftLeft(BitSet bs, int shift, int max) {
        BitSet res = new BitSet(max + 1);
        for (int i = bs.nextSetBit(0); i >= 0; i = bs.nextSetBit(i + 1)) {
            int ni = i + shift;
            if (ni > max) break;
            res.set(ni);
        }
        return res;
    }
}
